import{_ as s,C as d,o as i,c as l,a2 as n,E as o,w as r,a}from"./chunks/framework.D66Xq0Kv.js";const m=JSON.parse('{"title":"Debugging Flows","description":"","frontmatter":{},"headers":[],"relativePath":"guide/debugging.md","filePath":"guide/debugging.md"}'),h={name:"guide/debugging.md"};function g(p,t,u,b,w,T){const e=d("Screenshot");return i(),l("div",null,[t[9]||(t[9]=n('<h1 id="debugging-flows" tabindex="-1">Debugging Flows <a class="header-anchor" href="#debugging-flows" aria-label="Permalink to &quot;Debugging Flows&quot;">​</a></h1><p>FlowPilot gives you two views of a running flow: the FlowPilot Editor shows it live and lets you pause and step through it, and the in-game overlay draws it on screen. Both work during Play In Editor (PIE).</p><h2 id="watch-a-flow-run-in-the-editor" tabindex="-1">Watch a flow run in the editor <a class="header-anchor" href="#watch-a-flow-run-in-the-editor" aria-label="Permalink to &quot;Watch a flow run in the editor&quot;">​</a></h2><ol><li>Open the FlowPilot asset in its editor and press Play.</li><li>When an instance of the asset starts, the editor follows it automatically. To pick another one, use the <strong>Debug Target</strong> dropdown in the editor toolbar: it lists every running instance by Actor name, including Sub Flows and multiplayer clients.</li><li>A debug bar appears above the Tree View: <code>Debugging: BP_Door | Running</code>.</li></ol><p>Each Task row shows its state:</p><table tabindex="0"><thead><tr><th>Badge</th><th>Meaning</th></tr></thead><tbody><tr><td>Running (orange, row outlined)</td><td>The Task is executing.</td></tr><tr><td>Succeeded (green)</td><td>The Task finished successfully.</td></tr><tr><td>Failed (red)</td><td>The Task failed or errored.</td></tr><tr><td>Skipped (grey)</td><td>The Task is disabled.</td></tr><tr><td>Stopped Here (bright red)</td><td>Execution is paused at this Task.</td></tr></tbody></table><p>Tasks without a badge have not started yet.</p>',7)),o(e,{src:"screenshots/debugger-running.png"},{default:r(()=>[...t[0]||(t[0]=[a("The FlowPilot Editor during PIE: debug bar, a Running Task, earlier Tasks Succeeded, and the Debug Target dropdown open.",-1)])]),_:1}),t[10]||(t[10]=n('<h2 id="pause-on-a-task-with-breakpoints" tabindex="-1">Pause on a Task with breakpoints <a class="header-anchor" href="#pause-on-a-task-with-breakpoints" aria-label="Permalink to &quot;Pause on a Task with breakpoints&quot;">​</a></h2><p>A breakpoint pauses PIE the moment its Task starts.</p><ul><li><strong>Add or remove:</strong> click the gutter at the far left of a row (a faint red dot appears on hover), press <kbd>F9</kbd> on the selected Tasks, or use <strong>Toggle Breakpoint</strong> in the toolbar or right-click menu.</li><li><strong>Clear all</strong> for this asset: <kbd>Ctrl+Shift+F9</kbd>, or <strong>Clear Breakpoints</strong> in the right-click menu or Debug Target dropdown.</li><li><strong>When one is hit:</strong> PIE pauses, the FlowPilot Editor opens on the asset, and the Task is selected and marked <strong>Stopped Here</strong>. The debug bar reads <code>Stopped at &#39;Delay&#39;</code>.</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Breakpoints last for the editor session: they are not saved in the asset.</p></div>',4)),o(e,{src:"screenshots/breakpoints.png"},{default:r(()=>[...t[1]||(t[1]=[a("Two breakpoints in the gutter, and a hovered row showing the faint dot.",-1)])]),_:1}),o(e,{src:"screenshots/breakpoint-hit.png"},{default:r(()=>[...t[2]||(t[2]=[a('A breakpoint hit: the Task marked Stopped Here and the debug bar reading "Stopped at ...".',-1)])]),_:1}),t[11]||(t[11]=n('<h2 id="step-resume-and-stop" tabindex="-1">Step, resume and stop <a class="header-anchor" href="#step-resume-and-stop" aria-label="Permalink to &quot;Step, resume and stop&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Shortcut</th><th>What it does</th></tr></thead><tbody><tr><td>Resume</td><td><kbd>F5</kbd></td><td>Continues PIE.</td></tr><tr><td>Pause</td><td></td><td>Pauses PIE without a breakpoint.</td></tr><tr><td>Step</td><td><kbd>F10</kbd></td><td>Continues and pauses again when the next Task starts, on the same FlowPilot Component.</td></tr><tr><td>Stop</td><td></td><td>Ends the PIE session.</td></tr><tr><td>Show In Game</td><td></td><td>Turns on the in-game overlay for the instance you are debugging.</td></tr></tbody></table><p>The buttons are in the FlowPilot editor toolbar and on the debug bar. Shortcuts work while the FlowPilot Editor has focus. Step waits for the next Task to start, so stepping past a 2 second Delay takes 2 seconds of game time.</p>',3)),o(e,{src:"screenshots/debugger-toolbar.png"},{default:r(()=>[...t[3]||(t[3]=[a("The FlowPilot editor toolbar while paused: Toggle Breakpoint, Debug Target, Resume, Step, Stop and In-Game Debug.",-1)])]),_:1}),t[12]||(t[12]=n('<h2 id="see-flows-on-screen-with-the-in-game-overlay" tabindex="-1">See flows on screen with the in-game overlay <a class="header-anchor" href="#see-flows-on-screen-with-the-in-game-overlay" aria-label="Permalink to &quot;See flows on screen with the in-game overlay&quot;">​</a></h2><p>The overlay draws a FlowPilot Component&#39;s Task tree over the game view: running Tasks in orange, completed in green, queued in dark blue, with details such as <code>Task: 2 / 4</code> or <code>Loop 1/3</code> on active Tasks.</p><p>Turn it on from the <strong>FlowPilot</strong> dropdown in the Level Editor play toolbar, or <strong>In-Game Debug</strong> in the FlowPilot editor toolbar.</p>',3)),o(e,{src:"screenshots/level-editor-dropdown.png"},{default:r(()=>[...t[4]||(t[4]=[a("The FlowPilot dropdown in the Level Editor play toolbar during PIE.",-1)])]),_:1}),t[13]||(t[13]=n('<table tabindex="0"><thead><tr><th>Menu entry</th><th>Shows</th><th>Console command</th></tr></thead><tbody><tr><td>FlowPilotComponents List</td><td>Every component with its flow, state and index. Their Actors are outlined in the level.</td><td><code>fp.DebugList 1</code></td></tr><tr><td>Cached Actors</td><td>Actors cached by GameplayTag.</td><td><code>fp.DebugCache 1</code></td></tr><tr><td><code>[2] BP_Door - FP_DoorIntro</code></td><td>The Task tree of that component. The list fills in during PIE.</td><td><code>fp.DebugFlowPilot 2</code></td></tr><tr><td>Off</td><td>Nothing.</td><td><code>fp.DebugFlowPilot -1</code></td></tr></tbody></table><p>Only one overlay shows at a time. The console commands also work in packaged Development builds.</p>',2)),o(e,{src:"images/cmd_flowpilot.png"},{default:r(()=>[...t[5]||(t[5]=[a("A component's Task tree overlay (fp.DebugFlowPilot).",-1)])]),_:1}),o(e,{src:"images/cmd_list.png"},{default:r(()=>[...t[6]||(t[6]=[a("The FlowPilotComponents List overlay (fp.DebugList).",-1)])]),_:1}),o(e,{src:"images/cmd_cache.png"},{default:r(()=>[...t[7]||(t[7]=[a("The Cached Actors overlay (fp.DebugCache).",-1)])]),_:1}),t[14]||(t[14]=n('<h2 id="tune-the-overlay" tabindex="-1">Tune the overlay <a class="header-anchor" href="#tune-the-overlay" aria-label="Permalink to &quot;Tune the overlay&quot;">​</a></h2><p><strong>Debug Display Settings...</strong> at the bottom of the dropdown opens <strong>Project Settings › FlowPilot</strong>: font scale, colors, how many completed and queued Tasks to show, whether to draw the Root, and whether Task details show on active Tasks only. See <a href="/reference/settings/project-settings">Project Settings</a>.</p><p>To hide the FlowPilot dropdown from the Level Editor toolbar, untick <strong>Show In Game Debug In Level Editor Toolbar</strong> in the FlowPilot <a href="/reference/settings/editor-preferences">Editor Preferences</a> and restart the editor.</p>',3)),o(e,{src:"images/project_settings.png"},{default:r(()=>[...t[8]||(t[8]=[a("Project Settings › FlowPilot.",-1)])]),_:1})])}const f=s(h,[["render",g]]);export{m as __pageData,f as default};
